const list = document.querySelector('#todo');       // 첫 하나
const items = document.querySelectorAll('.item');   // 전부 (배열 아님)
[...items].filter((el) => el.dataset.done === '1'); // 배열로 바꿔 쓰기

// 빠르고 편하지만, 값이 사용자 입력이면 위험하다
el.innerHTML = `<b>${name}</b>`;      // name 에 <script> 가 오면?

// 안전한 기본값
const b = document.createElement('b');
b.textContent = name;                 // 태그가 아니라 글자로 들어간다
el.replaceChildren(b);

list.addEventListener('click', (e) => {
  const btn = e.target.closest('[data-action]');
  if (!btn) return;                       // 빈 곳을 눌렀다
  const id = btn.closest('li').dataset.id;
  if (btn.dataset.action === 'remove') remove(id);
});

let todos = [];                          // 진실은 여기 한 곳

function render() {
  list.replaceChildren(...todos.map((t) => {
    const li = document.createElement('li');
    li.dataset.id = t.id;
    li.textContent = t.text;
    return li;
  }));
}

function add(text) { todos = [...todos, { id: crypto.randomUUID(), text }]; render(); }
